public class Solution {
    public double Average(int[] salary) {
        int min = int.MaxValue;
        int max = int.MinValue;
        int sum = 0;

        foreach (int s in salary) {
            sum += s;
            if (s < min) min = s;
            if (s > max) max = s;
        }

        return (double)(sum - min - max) / (salary.Length - 2);
    }
}
