public class Solution {
    public string AbbreviateProduct(int left, int right) {
        System.Numerics.BigInteger product = System.Numerics.BigInteger.One;

        for (int i = left; i <= right; i++) {
            product *= i;
        }

        int zeros = 0;
        while (product % 10 == 0) {
            product /= 10;
            zeros++;
        }

        string s = product.ToString();

        if (s.Length > 10) {
            return s.Substring(0, 5) + "..." + s.Substring(s.Length - 5) + "e" + zeros;
        }

        return s + "e" + zeros;
    }
}
