        var nums = new List<string>();
        int n = str.Length;

        if (n == 1 || str[0] != '0') {
            nums.Add(str);
        }

        for (int i = 1; i < n; i++) {
            string integerPart = str.Substring(0, i);
            string fractionalPart = str.Substring(i);

            bool validIntegerPart = integerPart.Length == 1 || integerPart[0] != '0';
            bool validFractionalPart = fractionalPart[fractionalPart.Length - 1] != '0';

            if (validIntegerPart && validFractionalPart) {
                nums.Add(integerPart + "." + fractionalPart);
            }
        }

        return nums;
    }
