public class Solution {
    public int[] HitBricks(int[][] grid, int[][] hits) {
        int m = grid.Length;
        int n = grid[0].Length;
        int total = m * n;
        int roof = total;

        int[][] current = new int[m][];
        for (int i = 0; i < m; i++) {
            current[i] = (int[])grid[i].Clone();
        }

        foreach (int[] hit in hits) {
            current[hit[0]][hit[1]] = 0;
        }

        UnionFind uf = new UnionFind(total + 1);

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (current[r][c] == 0) continue;

                int id = r * n + c;

                if (r == 0) {
                    uf.Union(id, roof);
                }

                if (r > 0 && current[r - 1][c] == 1) {
                    uf.Union(id, (r - 1) * n + c);
                }

                if (c > 0 && current[r][c - 1] == 1) {
                    uf.Union(id, r * n + c - 1);
                }
            }
        }

        int[] result = new int[hits.Length];
        int[] dr = new int[] { -1, 1, 0, 0 };
        int[] dc = new int[] { 0, 0, -1, 1 };

        for (int i = hits.Length - 1; i >= 0; i--) {
            int r = hits[i][0];
            int c = hits[i][1];

            if (grid[r][c] == 0) {
                result[i] = 0;
                continue;
            }

            int before = uf.GetSize(roof);

            current[r][c] = 1;
            int id = r * n + c;

            if (r == 0) {
                uf.Union(id, roof);
            }

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];

                if (nr >= 0 && nr < m && nc >= 0 && nc < n && current[nr][nc] == 1) {
                    uf.Union(id, nr * n + nc);
                }
            }

            int after = uf.GetSize(roof);
            result[i] = System.Math.Max(0, after - before - 1);
        }

        return result;
    }

    private class UnionFind {
        private int[] parent;
        private int[] size;

        public UnionFind(int n) {
            parent = new int[n];
            size = new int[n];

            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int Find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }

            return x;
        }

        public void Union(int a, int b) {
            int rootA = Find(a);
            int rootB = Find(b);

            if (rootA == rootB) return;

            if (size[rootA] < size[rootB]) {
                int temp = rootA;
                rootA = rootB;
                rootB = temp;
            }

            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        public int GetSize(int x) {
            return size[Find(x)];
        }
    }
}
