public class Solution {
    public int NumFactoredBinaryTrees(int[] arr) {
        const long MOD = 1000000007L;

        System.Array.Sort(arr);
        int n = arr.Length;

        var index = new System.Collections.Generic.Dictionary<int, int>(n);
        for (int i = 0; i < n; i++) {
            index[arr[i]] = i;
        }

        long[] dp = new long[n];
        long answer = 0;

        for (int i = 0; i < n; i++) {
            dp[i] = 1;

            for (int j = 0; j < i; j++) {
                if (arr[i] % arr[j] == 0) {
                    int other = arr[i] / arr[j];

                    if (index.TryGetValue(other, out int k) && k < i) {
                        dp[i] = (dp[i] + dp[j] * dp[k]) % MOD;
                    }
                }
            }

            answer = (answer + dp[i]) % MOD;
        }

        return (int)answer;
    }
}
