public class Solution {
    public int Clumsy(int n) {
        int[] stack = new int[n + 1];
        int top = 0;
        stack[top] = n;

        int op = 0;
        for (int i = n - 1; i >= 1; i--) {
            if (op == 0) {
                stack[top] *= i;
            } else if (op == 1) {
                stack[top] /= i;
            } else if (op == 2) {
                stack[++top] = i;
            } else {
                stack[++top] = -i;
            }

            op = (op + 1) % 4;
        }

        int result = 0;
        for (int i = 0; i <= top; i++) {
            result += stack[i];
        }

        return result;
    }
}
