using System.Collections.Generic;

public class MKAverage {
    private const int MaxValue = 100000;

    private readonly int m;
    private readonly int k;
    private readonly Queue<int> window;
    private readonly Fenwick countTree;
    private readonly Fenwick sumTree;

    public MKAverage(int m, int k) {
        this.m = m;
        this.k = k;
        this.window = new Queue<int>();
        this.countTree = new Fenwick(MaxValue);
        this.sumTree = new Fenwick(MaxValue);
    }

    public void AddElement(int num) {
        window.Enqueue(num);
        countTree.Add(num, 1);
        sumTree.Add(num, num);

        if (window.Count > m) {
            int removed = window.Dequeue();
            countTree.Add(removed, -1);
            sumTree.Add(removed, -removed);
        }
    }

    public int CalculateMKAverage() {
        if (window.Count < m) {
            return -1;
        }

        long middleSum = SumSmallest(m - k) - SumSmallest(k);
        return (int)(middleSum / (m - 2 * k));
    }

    private long SumSmallest(int count) {
        if (count <= 0) {
            return 0;
        }

        int value = countTree.FindKth(count);
        long countLess = countTree.Query(value - 1);
        long sumLess = sumTree.Query(value - 1);

        return sumLess + (long)(count - countLess) * value;
    }

    private class Fenwick {
        private readonly int n;
        private readonly long[] tree;

        public Fenwick(int n) {
            this.n = n;
            this.tree = new long[n + 1];
        }

        public void Add(int index, long delta) {
            for (int i = index; i <= n; i += i & -i) {
                tree[i] += delta;
            }
        }

        public long Query(int index) {
            long result = 0;

            for (int i = index; i > 0; i -= i & -i) {
                result += tree[i];
            }

            return result;
        }

        public int FindKth(long target) {
            int index = 0;
            int bit = 1;

            while ((bit << 1) <= n) {
                bit <<= 1;
            }

            while (bit > 0) {
                int next = index + bit;

                if (next <= n && tree[next] < target) {
                    index = next;
                    target -= tree[next];
                }

                bit >>= 1;
            }

            return index + 1;
        }
    }
}
```

