public class Solution {
    public int[] NumSmallerByFrequency(string[] queries, string[] words) {
        int F(string s) {
            char smallest = '{';
            int count = 0;

            foreach (char c in s) {
                if (c < smallest) {
                    smallest = c;
                    count = 1;
                } else if (c == smallest) {
                    count++;
                }
            }

            return count;
        }

        int[] wordFreq = new int[words.Length];
        for (int i = 0; i < words.Length; i++) {
            wordFreq[i] = F(words[i]);
        }

        System.Array.Sort(wordFreq);

        int[] answer = new int[queries.Length];

        for (int i = 0; i < queries.Length; i++) {
            int queryFreq = F(queries[i]);

            int left = 0;
            int right = wordFreq.Length;

            while (left < right) {
                int mid = left + (right - left) / 2;

                if (wordFreq[mid] <= queryFreq) {
                    left = mid + 1;
                } else {
                    right = mid;
                }
            }

            answer[i] = wordFreq.Length - left;
        }

        return answer;
    }
}
