public class Solution {
    public bool CanCross(int[] stones) {
        int n = stones.Length;
        if (n == 1) return true;
        if (stones[1] != 1) return false;

        var index = new System.Collections.Generic.Dictionary<int, int>();
        for (int i = 0; i < n; i++) {
            index[stones[i]] = i;
        }

        bool[,] dp = new bool[n, n + 1];
        dp[0, 0] = true;

        for (int i = 0; i < n; i++) {
            for (int k = 0; k <= n; k++) {
                if (!dp[i, k]) continue;

                for (int delta = -1; delta <= 1; delta++) {
                    int nextJump = k + delta;
                    if (nextJump <= 0 || nextJump > n) continue;

                    long nextPosLong = (long)stones[i] + nextJump;
                    if (nextPosLong > int.MaxValue) continue;

                    int nextPos = (int)nextPosLong;
                    if (index.TryGetValue(nextPos, out int nextIndex)) {
                        if (nextIndex == n - 1) return true;
                        dp[nextIndex, nextJump] = true;
                    }
                }
            }
        }

        return false;
    }
}
