    public int MaxEqualFreq(int[] nums) {
        int n = nums.Length;
        int[] counts = new int[100001];
        int[] freqCounts = new int[n + 2];

        int maxFreq = 0;
        int answer = 0;

        for (int i = 0; i < n; i++) {
            int num = nums[i];
            int oldFreq = counts[num];

            if (oldFreq > 0) {
                freqCounts[oldFreq]--;
            }

            int newFreq = oldFreq + 1;
            counts[num] = newFreq;
            freqCounts[newFreq]++;

            if (newFreq > maxFreq) {
                maxFreq = newFreq;
