            int length = i + 1;

            if (maxFreq == 1 ||
                maxFreq * freqCounts[maxFreq] + 1 == length ||
                (maxFreq - 1) * (freqCounts[maxFreq - 1] + 1) + 1 == length) {
                answer = length;
