public class Solution {
    public int MaxTotalFruits(int[][] fruits, int startPos, int k) {
        int n = fruits.Length;
        int left = 0;
        long sum = 0;
        long ans = 0;

        for (int right = 0; right < n; right++) {
            sum += fruits[right][1];

            while (left <= right && Steps(fruits[left][0], fruits[right][0], startPos) > k) {
                sum -= fruits[left][1];
                left++;
            }

            if (sum > ans) ans = sum;
        }

        return (int)ans;
    }

    private int Steps(int leftPos, int rightPos, int startPos) {
        if (rightPos <= startPos) {
            return startPos - leftPos;
        }

        if (leftPos >= startPos) {
            return rightPos - startPos;
        }

        int leftDist = startPos - leftPos;
        int rightDist = rightPos - startPos;

        return System.Math.Min(leftDist * 2 + rightDist, leftDist + rightDist * 2);
    }
}
