public class Solution {
    public int LargestMagicSquare(int[][] grid) {
        int m = grid.Length;
        int n = grid[0].Length;

        long[,] rowPrefix = new long[m, n + 1];
        long[,] colPrefix = new long[m + 1, n];
        long[,] diagPrefix = new long[m + 1, n + 1];
        long[,] antiDiagPrefix = new long[m + 1, n + 1];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                rowPrefix[i, j + 1] = rowPrefix[i, j] + grid[i][j];
                colPrefix[i + 1, j] = colPrefix[i, j] + grid[i][j];
                diagPrefix[i + 1, j + 1] = diagPrefix[i, j] + grid[i][j];
                antiDiagPrefix[i + 1, j] = antiDiagPrefix[i, j + 1] + grid[i][j];
            }
        }

        int maxSize = System.Math.Min(m, n);

        for (int k = maxSize; k >= 1; k--) {
            for (int r = 0; r + k <= m; r++) {
                for (int c = 0; c + k <= n; c++) {
                    long target = diagPrefix[r + k, c + k] - diagPrefix[r, c];
                    long anti = antiDiagPrefix[r + k, c] - antiDiagPrefix[r, c + k];

                    if (anti != target) {
                        continue;
                    }

                    bool valid = true;

                    for (int i = r; i < r + k && valid; i++) {
                        long sum = rowPrefix[i, c + k] - rowPrefix[i, c];
                        if (sum != target) {
                            valid = false;
                        }
                    }

                    for (int j = c; j < c + k && valid; j++) {
                        long sum = colPrefix[r + k, j] - colPrefix[r, j];
                        if (sum != target) {
                            valid = false;
                        }
                    }

                    if (valid) {
                        return k;
                    }
                }
            }
        }

        return 1;
    }
}
