public class Solution {
    public long MaximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial) {
        int n = flowers.Length;
        int[] arr = new int[n];
        int m = 0;
        int alreadyFull = 0;

        for (int i = 0; i < n; i++) {
            if (flowers[i] >= target) {
                alreadyFull++;
            } else {
                arr[m++] = flowers[i];
            }
        }

        if (m == 0) {
            return (long)n * full;
        }

        Array.Sort(arr, 0, m);

        long[] prefix = new long[m + 1];
        for (int i = 0; i < m; i++) {
            prefix[i + 1] = prefix[i] + arr[i];
        }

        int UpperBound(int len, int value) {
            int left = 0;
            int right = len;

            while (left < right) {
                int mid = left + (right - left) / 2;
                if (arr[mid] <= value) {
                    left = mid + 1;
                } else {
                    right = mid;
                }
            }

            return left;
        }

        long CostToReach(int len, int level) {
            int count = UpperBound(len, level);
            return (long)level * count - prefix[count];
        }

        int BestPartialLevel(int len, long budget) {
            int left = 0;
            int right = target - 1;
            int best = 0;

            while (left <= right) {
                int mid = left + (right - left) / 2;
                if (CostToReach(len, mid) <= budget) {
                    best = mid;
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }

            return best;
        }

        long answer = 0;
        long costFull = 0;

        for (int madeFull = 0; madeFull <= m; madeFull++) {
            if (costFull <= newFlowers) {
                int remainingIncomplete = m - madeFull;
                long beauty = (long)(alreadyFull + madeFull) * full;

                if (remainingIncomplete > 0) {
                    long remainingFlowers = newFlowers - costFull;
                    int level = BestPartialLevel(remainingIncomplete, remainingFlowers);
                    beauty += (long)level * partial;
                }

                if (beauty > answer) {
                    answer = beauty;
                }
            }

            if (madeFull < m) {
                costFull += (long)target - arr[m - 1 - madeFull];
            }
        }

        return answer;
    }
}
