public class Solution {
    public int MinMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.Length;
        int bestNode = int.MaxValue;
        int bestInfected = int.MaxValue;

        foreach (int removed in initial) {
            bool[] infected = new bool[n];
            int[] queue = new int[n];
            int head = 0, tail = 0;
            int count = 0;

            foreach (int node in initial) {
                if (node == removed) continue;
                infected[node] = true;
                queue[tail++] = node;
                count++;
            }

            while (head < tail) {
                int cur = queue[head++];

                for (int next = 0; next < n; next++) {
                    if (next == removed || infected[next]) continue;

                    if (graph[cur][next] == 1) {
                        infected[next] = true;
                        queue[tail++] = next;
                        count++;
                    }
                }
            }

            if (count < bestInfected || (count == bestInfected && removed < bestNode)) {
                bestInfected = count;
                bestNode = removed;
            }
        }

        return bestNode;
    }
}
