public class Solution {
    public int LongestStrChain(string[] words) {
        Array.Sort(words, (a, b) => a.Length.CompareTo(b.Length));

        Dictionary<string, int> dp = new Dictionary<string, int>();
        int answer = 1;

        foreach (string word in words) {
            int best = 1;

            for (int i = 0; i < word.Length; i++) {
                string predecessor = word.Remove(i, 1);

                if (dp.TryGetValue(predecessor, out int previousLength)) {
                    best = Math.Max(best, previousLength + 1);
                }
            }

            if (dp.TryGetValue(word, out int currentLength)) {
                dp[word] = Math.Max(currentLength, best);
            } else {
                dp[word] = best;
            }

            answer = Math.Max(answer, dp[word]);
        }

        return answer;
    }
}
