public class Solution {
    public int MinCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = passingFees.Length;
        int inf = 1_000_000_000;

        int[][] dp = new int[maxTime + 1][];
        for (int t = 0; t <= maxTime; t++) {
            dp[t] = new int[n];
            for (int i = 0; i < n; i++) {
                dp[t][i] = inf;
            }
        }

        dp[0][0] = passingFees[0];

        for (int t = 1; t <= maxTime; t++) {
            foreach (int[] edge in edges) {
                int u = edge[0];
                int v = edge[1];
                int time = edge[2];

                if (t >= time) {
                    if (dp[t - time][u] != inf) {
                        int cost = dp[t - time][u] + passingFees[v];
                        if (cost < dp[t][v]) {
                            dp[t][v] = cost;
                        }
                    }

                    if (dp[t - time][v] != inf) {
                        int cost = dp[t - time][v] + passingFees[u];
                        if (cost < dp[t][u]) {
                            dp[t][u] = cost;
                        }
                    }
                }
            }
        }

        int answer = inf;
        for (int t = 0; t <= maxTime; t++) {
            if (dp[t][n - 1] < answer) {
                answer = dp[t][n - 1];
            }
        }

        return answer == inf ? -1 : answer;
    }
}
