public class Solution {
    public int MinDays(int[][] grid) {
        if (CountIslands(grid) != 1) {
            return 0;
        }

        int m = grid.Length;
        int n = grid[0].Length;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    grid[i][j] = 0;

                    if (CountIslands(grid) != 1) {
                        return 1;
                    }

                    grid[i][j] = 1;
                }
            }
        }

        return 2;
    }

    private int CountIslands(int[][] grid) {
        int m = grid.Length;
        int n = grid[0].Length;
        bool[,] visited = new bool[m, n];
        int islands = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1 && !visited[i, j]) {
                    islands++;
                    if (islands > 1) {
                        return islands;
                    }

                    Dfs(grid, visited, i, j);
                }
            }
        }

        return islands;
    }

    private void Dfs(int[][] grid, bool[,] visited, int row, int col) {
        int m = grid.Length;
        int n = grid[0].Length;

        if (row < 0 || row >= m || col < 0 || col >= n) {
            return;
        }

        if (grid[row][col] == 0 || visited[row, col]) {
            return;
        }

        visited[row, col] = true;

        Dfs(grid, visited, row + 1, col);
        Dfs(grid, visited, row - 1, col);
        Dfs(grid, visited, row, col + 1);
        Dfs(grid, visited, row, col - 1);
    }
}
