            for (int mentorIndex = 0; mentorIndex < m; mentorIndex++) {
                if ((mask & (1 << mentorIndex)) == 0) {
                    int nextMask = mask | (1 << mentorIndex);
                    int newScore = dp[mask] + score[studentIndex][mentorIndex];
                    if (newScore > dp[nextMask]) {
