public class Solution {
    public int MaxSumTwoNoOverlap(int[] nums, int firstLen, int secondLen) {
        int n = nums.Length;
        int[] prefix = new int[n + 1];

        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        int MaxWithOrder(int leftLen, int rightLen) {
            int bestLeft = 0;
            int bestTotal = 0;

            for (int end = leftLen + rightLen; end <= n; end++) {
                int leftSum = prefix[end - rightLen] - prefix[end - rightLen - leftLen];
                bestLeft = System.Math.Max(bestLeft, leftSum);

                int rightSum = prefix[end] - prefix[end - rightLen];
                bestTotal = System.Math.Max(bestTotal, bestLeft + rightSum);
            }

            return bestTotal;
        }

        return System.Math.Max(
            MaxWithOrder(firstLen, secondLen),
            MaxWithOrder(secondLen, firstLen)
        );
    }
}
