public class Solution {
    public int MinAreaRect(int[][] points) {
        var columns = new System.Collections.Generic.Dictionary<int, System.Collections.Generic.List<int>>();

        foreach (var point in points) {
            int x = point[0];
            int y = point[1];

            if (!columns.ContainsKey(x)) {
                columns[x] = new System.Collections.Generic.List<int>();
            }

            columns[x].Add(y);
        }

        var xs = new System.Collections.Generic.List<int>(columns.Keys);
        xs.Sort();

        var lastXForYPair = new System.Collections.Generic.Dictionary<long, int>();
        int minArea = int.MaxValue;

        foreach (int x in xs) {
            var ys = columns[x];
            ys.Sort();

            for (int i = 0; i < ys.Count; i++) {
                for (int j = i + 1; j < ys.Count; j++) {
                    int y1 = ys[i];
                    int y2 = ys[j];
                    long key = ((long)y1 << 32) | (uint)y2;

                    if (lastXForYPair.ContainsKey(key)) {
                        int width = x - lastXForYPair[key];
                        int height = y2 - y1;
                        minArea = System.Math.Min(minArea, width * height);
                    }

                    lastXForYPair[key] = x;
                }
            }
        }

        return minArea == int.MaxValue ? 0 : minArea;
    }
}
