public class Solution {
    public int MinDays(int[] bloomDay, int m, int k) {
        int n = bloomDay.Length;

        if ((long)m * k > n) {
            return -1;
        }

        int left = int.MaxValue;
        int right = int.MinValue;

        foreach (int day in bloomDay) {
            if (day < left) left = day;
            if (day > right) right = day;
        }

        while (left < right) {
            int mid = left + (right - left) / 2;

            if (CanMake(bloomDay, m, k, mid)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        return left;
    }

    private bool CanMake(int[] bloomDay, int m, int k, int day) {
        int bouquets = 0;
        int consecutive = 0;

        foreach (int bloom in bloomDay) {
            if (bloom <= day) {
                consecutive++;

                if (consecutive == k) {
                    bouquets++;
                    if (bouquets >= m) {
                        return true;
                    }
                    consecutive = 0;
                }
            } else {
                consecutive = 0;
            }
        }

        return false;
    }
}
