public class Solution {
    public int MaxSizeSlices(int[] slices) {
        int total = slices.Length;
        int pick = total / 3;

        return System.Math.Max(
            MaxLinear(slices, 0, total - 2, pick),
            MaxLinear(slices, 1, total - 1, pick)
        );
    }

    private int MaxLinear(int[] slices, int start, int end, int pick) {
        int len = end - start + 1;
        int neg = -1000000000;
        int[,] dp = new int[len + 1, pick + 1];

        for (int i = 0; i <= len; i++) {
            for (int j = 0; j <= pick; j++) {
                dp[i, j] = neg;
            }
        }

        for (int i = 0; i <= len; i++) {
            dp[i, 0] = 0;
        }

        for (int i = 1; i <= len; i++) {
            int value = slices[start + i - 1];
            for (int j = 1; j <= pick; j++) {
                dp[i, j] = dp[i - 1, j];

                int prevIndex = i >= 2 ? i - 2 : 0;
                if (dp[prevIndex, j - 1] != neg) {
                    dp[i, j] = System.Math.Max(dp[i, j], dp[prevIndex, j - 1] + value);
                }
            }
        }

        return dp[len, pick];
    }
}
