public class Solution {
    private int[] parent;
    private int[] rank;

    public bool[] FriendRequests(int n, int[][] restrictions, int[][] requests) {
        parent = new int[n];
        rank = new int[n];

        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }

        bool[] result = new bool[requests.Length];

        for (int i = 0; i < requests.Length; i++) {
            int u = requests[i][0];
            int v = requests[i][1];

            int rootU = Find(u);
            int rootV = Find(v);

            if (rootU == rootV) {
                result[i] = true;
                continue;
            }

            bool canAccept = true;

            foreach (int[] restriction in restrictions) {
                int rootA = Find(restriction[0]);
                int rootB = Find(restriction[1]);

                if ((rootA == rootU && rootB == rootV) || (rootA == rootV && rootB == rootU)) {
                    canAccept = false;
                    break;
                }
            }

            if (canAccept) {
                Union(rootU, rootV);
                result[i] = true;
            } else {
                result[i] = false;
            }
        }

        return result;
    }

    private int Find(int x) {
        if (parent[x] != x) {
            parent[x] = Find(parent[x]);
        }

        return parent[x];
    }

    private void Union(int x, int y) {
        int rootX = Find(x);
        int rootY = Find(y);

        if (rootX == rootY) {
            return;
        }

        if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
        } else if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    }
}
