public class Solution {
    public int[] NextGreaterElements(int[] nums) {
        int n = nums.Length;
        int[] result = new int[n];

        for (int i = 0; i < n; i++) {
            result[i] = -1;
        }

        int[] stack = new int[n];
        int top = -1;

        for (int i = 0; i < 2 * n; i++) {
            int index = i % n;

            while (top >= 0 && nums[stack[top]] < nums[index]) {
                result[stack[top]] = nums[index];
                top--;
            }

            if (i < n) {
                stack[++top] = index;
            }
        }

        return result;
    }
}
