using System.Collections.Generic;
using System.Text;

public class Solution {
    public IList<string> RemoveInvalidParentheses(string s) {
        int leftRemove = 0;
        int rightRemove = 0;

        foreach (char c in s) {
            if (c == '(') {
                leftRemove++;
            } else if (c == ')') {
                if (leftRemove == 0) {
                    rightRemove++;
                } else {
                    leftRemove--;
                }
            }
        }

        int n = s.Length;
        int[] suffixLeft = new int[n + 1];
        int[] suffixRight = new int[n + 1];

        for (int i = n - 1; i >= 0; i--) {
            suffixLeft[i] = suffixLeft[i + 1] + (s[i] == '(' ? 1 : 0);
            suffixRight[i] = suffixRight[i + 1] + (s[i] == ')' ? 1 : 0);
        }

        HashSet<string> result = new HashSet<string>();
        StringBuilder path = new StringBuilder();

        void Dfs(int index, int open, int leftRem, int rightRem) {
            if (leftRem < 0 || rightRem < 0 || open < 0) return;
            if (leftRem > suffixLeft[index] || rightRem > suffixRight[index]) return;
            if (open > suffixRight[index] - rightRem) return;

            if (index == n) {
                result.Add(path.ToString());
                return;
            }

            char c = s[index];
            int len = path.Length;

            if (c == '(') {
                Dfs(index + 1, open, leftRem - 1, rightRem);

                path.Append(c);
                Dfs(index + 1, open + 1, leftRem, rightRem);
                path.Length = len;
            } else if (c == ')') {
                Dfs(index + 1, open, leftRem, rightRem - 1);

                if (open > 0) {
                    path.Append(c);
                    Dfs(index + 1, open - 1, leftRem, rightRem);
                    path.Length = len;
                }
            } else {
                path.Append(c);
                Dfs(index + 1, open, leftRem, rightRem);
                path.Length = len;
            }
        }

        Dfs(0, 0, leftRemove, rightRemove);

        return new List<string>(result);
    }
}
