public class Solution {
    public double[] MedianSlidingWindow(int[] nums, int k) {
        int n = nums.Length;
        double[] ans = new double[n - k + 1];

        var small = new SortedSet<(int value, int index)>();
        var large = new SortedSet<(int value, int index)>();

        void Rebalance() {
            while (small.Count > large.Count + 1) {
                var x = small.Max;
                small.Remove(x);
                large.Add(x);
            }

            while (small.Count < large.Count) {
                var x = large.Min;
                large.Remove(x);
                small.Add(x);
            }
        }

        void Add((int value, int index) x) {
            if (small.Count == 0 || x.CompareTo(small.Max) <= 0) {
                small.Add(x);
            } else {
                large.Add(x);
            }

            Rebalance();
        }

        void Remove((int value, int index) x) {
            if (!small.Remove(x)) {
                large.Remove(x);
            }

            Rebalance();
        }

        double GetMedian() {
            if ((k & 1) == 1) {
                return small.Max.value;
            }

            return ((long)small.Max.value + (long)large.Min.value) / 2.0;
        }

        for (int i = 0; i < n; i++) {
            Add((nums[i], i));

            if (i >= k) {
                Remove((nums[i - k], i - k));
            }

            if (i >= k - 1) {
                ans[i - k + 1] = GetMedian();
            }
        }

        return ans;
    }
}
