public class Solution {
    public int SplitArray(int[] nums, int k) {
        long left = 0;
        long right = 0;

        foreach (int num in nums) {
            left = System.Math.Max(left, num);
            right += num;
        }

        while (left < right) {
            long mid = left + (right - left) / 2;

            if (CanSplit(nums, k, mid)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        return (int)left;
    }

    private bool CanSplit(int[] nums, int k, long maxAllowedSum) {
        int subarrays = 1;
        long currentSum = 0;

        foreach (int num in nums) {
            if (currentSum + num > maxAllowedSum) {
                subarrays++;
                currentSum = num;

                if (subarrays > k) {
                    return false;
                }
            } else {
                currentSum += num;
            }
        }

        return true;
    }
}
