        var useful = new System.Collections.Generic.List<int[]>();

        foreach (string sticker in stickers) {
            int[] cnt = new int[26];
            bool hasUseful = false;

            foreach (char ch in sticker) {
                int idx = ch - 'a';
                if (needed[idx]) {
                    cnt[idx]++;
                    covered[idx] = true;
                    hasUseful = true;
                }
            }

            if (hasUseful) {
                bool dominated = false;

                for (int i = 0; i < useful.Count; i++) {
                    if (IsSubset(cnt, useful[i])) {
                        dominated = true;
                        break;
                    }

                    if (IsSubset(useful[i], cnt)) {
                        useful.RemoveAt(i);
                        i--;
                    }
                }

                if (!dominated) {
                    useful.Add(cnt);
                }
            }
        }

        foreach (char ch in target) {
            if (!covered[ch - 'a']) {
                return -1;
            }
        }

        int[] targetCount = new int[26];
        foreach (char ch in target) {
            targetCount[ch - 'a']++;
        }

        string start = BuildString(targetCount);
        var memo = new System.Collections.Generic.Dictionary<string, int>();
        memo[""] = 0;

        int ans = Dfs(start);
        return ans >= 1000000 ? -1 : ans;

        int Dfs(string remaining) {
            if (memo.ContainsKey(remaining)) {
                return memo[remaining];
            }

            int[] need = new int[26];
            foreach (char ch in remaining) {
                need[ch - 'a']++;
            }

            int first = remaining[0] - 'a';
            int best = 1000000;

            foreach (int[] sticker in useful) {
                if (sticker[first] == 0) {
                    continue;
                }

                int[] next = new int[26];
                for (int i = 0; i < 26; i++) {
                    next[i] = System.Math.Max(0, need[i] - sticker[i]);
                }

                int sub = Dfs(BuildString(next));
                if (sub != 1000000) {
                    best = System.Math.Min(best, sub + 1);
                }
            }

            memo[remaining] = best;
            return best;
        }
    }

    private bool IsSubset(int[] a, int[] b) {
        for (int i = 0; i < 26; i++) {
            if (a[i] > b[i]) {
                return false;
            }
        }
        return true;
    }

    private string BuildString(int[] count) {
        var sb = new System.Text.StringBuilder();

        for (int i = 0; i < 26; i++) {
            for (int j = 0; j < count[i]; j++) {
                sb.Append((char)('a' + i));
            }
        }

        return sb.ToString();
    }
}
