public class Solution {
    public int RegionsBySlashes(string[] grid) {
        int n = grid.Length;
        int total = n * n * 4;
        DSU dsu = new DSU(total);

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int baseIndex = (r * n + c) * 4;
                char ch = grid[r][c];

                if (ch == ' ') {
                    dsu.Union(baseIndex + 0, baseIndex + 1);
                    dsu.Union(baseIndex + 1, baseIndex + 2);
                    dsu.Union(baseIndex + 2, baseIndex + 3);
                } else if (ch == '/') {
                    dsu.Union(baseIndex + 0, baseIndex + 3);
                    dsu.Union(baseIndex + 1, baseIndex + 2);
                } else {
                    dsu.Union(baseIndex + 0, baseIndex + 1);
                    dsu.Union(baseIndex + 2, baseIndex + 3);
                }

                if (r + 1 < n) {
                    int belowIndex = ((r + 1) * n + c) * 4;
                    dsu.Union(baseIndex + 2, belowIndex + 0);
                }

                if (c + 1 < n) {
                    int rightIndex = (r * n + c + 1) * 4;
                    dsu.Union(baseIndex + 1, rightIndex + 3);
                }
            }
        }

        return dsu.Count;
    }

    private class DSU {
        private int[] parent;
        private int[] rank;
        public int Count { get; private set; }

        public DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            Count = n;

            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public int Find(int x) {
            if (parent[x] != x) {
                parent[x] = Find(parent[x]);
            }

            return parent[x];
        }

        public void Union(int a, int b) {
            int rootA = Find(a);
            int rootB = Find(b);

            if (rootA == rootB) {
                return;
            }

            if (rank[rootA] < rank[rootB]) {
                parent[rootA] = rootB;
            } else if (rank[rootA] > rank[rootB]) {
                parent[rootB] = rootA;
            } else {
                parent[rootB] = rootA;
                rank[rootA]++;
            }

            Count--;
        }
    }
}
