public class Solution {
    public int[] SortByBits(int[] arr) {
        System.Array.Sort(arr, (a, b) => {
            int bitsA = CountBits(a);
            int bitsB = CountBits(b);

            if (bitsA != bitsB) {
                return bitsA - bitsB;
            }

            return a - b;
        });

        return arr;
    }

    private int CountBits(int num) {
        int count = 0;

        while (num > 0) {
            count += num & 1;
            num >>= 1;
        }

        return count;
    }
