using System;
using System.Collections.Generic;

public class Solution {
    private Dictionary<int, int[]> memo;

    public int[] EarliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memo = new Dictionary<int, int[]>();
        return Dfs(n, firstPlayer, secondPlayer);
    }

    private int[] Dfs(int m, int a, int b) {
        if (a + b == m + 1) {
            return new int[] { 1, 1 };
        }

        int key = (m << 10) | (a << 5) | b;
        if (memo.ContainsKey(key)) {
            return memo[key];
        }

        int half = m / 2;
        int nextM = (m + 1) / 2;
        HashSet<int> nextStates = new HashSet<int>();

        void Enumerate(int i, int countLessA, int countLessB) {
            if (i > half) {
                int ca = countLessA;
                int cb = countLessB;

                if ((m & 1) == 1) {
                    int mid = (m + 1) / 2;
                    if (mid < a) ca++;
                    if (mid < b) cb++;
                }

                int nextA = ca + 1;
                int nextB = cb + 1;
                nextStates.Add((nextA << 5) | nextB);
                return;
            }

            int left = i;
            int right = m + 1 - i;

            if (left == a || right == a) {
                int ca = countLessA;
                int cb = countLessB;
                if (a < b) cb++;
                Enumerate(i + 1, ca, cb);
            } else if (left == b || right == b) {
                Enumerate(i + 1, countLessA, countLessB);
            } else {
                int ca1 = countLessA;
                int cb1 = countLessB;
                if (left < a) ca1++;
                if (left < b) cb1++;
                Enumerate(i + 1, ca1, cb1);

                int ca2 = countLessA;
                int cb2 = countLessB;
                if (right < a) ca2++;
                if (right < b) cb2++;
                Enumerate(i + 1, ca2, cb2);
            }
        }

        Enumerate(1, 0, 0);

        int earliest = int.MaxValue;
        int latest = int.MinValue;

        foreach (int state in nextStates) {
            int nextA = state >> 5;
            int nextB = state & 31;

            int[] result = Dfs(nextM, nextA, nextB);
            earliest = Math.Min(earliest, result[0] + 1);
            latest = Math.Max(latest, result[1] + 1);
        }

        memo[key] = new int[] { earliest, latest };
        return memo[key];
    }
}
