public class Solution {
    public IList<IList<string>> SuggestedProducts(string[] products, string searchWord) {
        Array.Sort(products, StringComparer.Ordinal);

        IList<IList<string>> result = new List<IList<string>>();
        int n = products.Length;

        for (int i = 1; i <= searchWord.Length; i++) {
            string prefix = searchWord.Substring(0, i);
            int start = LowerBound(products, prefix);

            IList<string> suggestions = new List<string>();

            for (int j = start; j < n && suggestions.Count < 3; j++) {
                if (products[j].StartsWith(prefix, StringComparison.Ordinal)) {
                    suggestions.Add(products[j]);
                } else {
                    break;
                }
            }

            result.Add(suggestions);
        }

        return result;
    }

    private int LowerBound(string[] products, string target) {
        int left = 0;
        int right = products.Length;

        while (left < right) {
            int mid = left + (right - left) / 2;

            if (string.CompareOrdinal(products[mid], target) < 0) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        return left;
    }
}
