using System;
using System.Collections.Generic;

public class Solution {
    public int[] GetCoprimes(int[] nums, int[][] edges) {
        int n = nums.Length;
        int[] ans = new int[n];
        Array.Fill(ans, -1);

        List<int>[] graph = new List<int>[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new List<int>();
        }

        foreach (int[] edge in edges) {
            int u = edge[0];
            int v = edge[1];
            graph[u].Add(v);
            graph[v].Add(u);
        }

        List<int>[] coprimeValues = new List<int>[51];
        for (int i = 1; i <= 50; i++) {
            coprimeValues[i] = new List<int>();
            for (int j = 1; j <= 50; j++) {
                if (Gcd(i, j) == 1) {
                    coprimeValues[i].Add(j);
                }
            }
        }

        List<int>[] nodesByValue = new List<int>[51];
        List<int>[] depthsByValue = new List<int>[51];

        for (int i = 0; i <= 50; i++) {
            nodesByValue[i] = new List<int>();
            depthsByValue[i] = new List<int>();
        }

        Stack<(int node, int parent, int depth, int state)> stack = new Stack<(int node, int parent, int depth, int state)>();
        stack.Push((0, -1, 0, 0));

        while (stack.Count > 0) {
            var frame = stack.Pop();
            int node = frame.node;
            int parent = frame.parent;
            int depth = frame.depth;

            if (frame.state == 0) {
                int value = nums[node];

                int bestNode = -1;
                int bestDepth = -1;

                foreach (int candidateValue in coprimeValues[value]) {
                    int count = nodesByValue[candidateValue].Count;
                    if (count > 0) {
                        int candidateDepth = depthsByValue[candidateValue][count - 1];
                        if (candidateDepth > bestDepth) {
                            bestDepth = candidateDepth;
                            bestNode = nodesByValue[candidateValue][count - 1];
                        }
                    }
                }

                ans[node] = bestNode;

                nodesByValue[value].Add(node);
                depthsByValue[value].Add(depth);

                stack.Push((node, parent, depth, 1));

                foreach (int next in graph[node]) {
                    if (next != parent) {
                        stack.Push((next, node, depth + 1, 0));
                    }
                }
            } else {
                int value = nums[node];
                nodesByValue[value].RemoveAt(nodesByValue[value].Count - 1);
                depthsByValue[value].RemoveAt(depthsByValue[value].Count - 1);
            }
        }

        return ans;
    }

    private int Gcd(int a, int b) {
        while (b != 0) {
            int temp = a % b;
            a = b;
            b = temp;
        }

        return a;
    }
}
