public class Solution {
    private string[] words;
    private string result;
    private int[] map;
    private bool[] used;
    private bool[] noZero;

    public bool IsSolvable(string[] words, string result) {
        this.words = words;
        this.result = result;

        int maxWordLen = 0;
        foreach (string word in words) {
            if (word.Length > maxWordLen) maxWordLen = word.Length;
        }

        if (result.Length < maxWordLen || result.Length > maxWordLen + 1) {
            return false;
        }

        map = new int[26];
        for (int i = 0; i < 26; i++) map[i] = -1;

        used = new bool[10];
        noZero = new bool[26];

        bool[] seen = new bool[26];
        int uniqueCount = 0;

        foreach (string word in words) {
            if (word.Length > 1) noZero[word[0] - 'A'] = true;

            foreach (char ch in word) {
                int idx = ch - 'A';
                if (!seen[idx]) {
                    seen[idx] = true;
                    uniqueCount++;
                }
            }
        }

        if (result.Length > 1) noZero[result[0] - 'A'] = true;

        foreach (char ch in result) {
            int idx = ch - 'A';
            if (!seen[idx]) {
                seen[idx] = true;
                uniqueCount++;
            }
        }

        if (uniqueCount > 10) return false;

        return Dfs(0, 0, 0);
    }

    private bool Dfs(int col, int row, int sum) {
        if (col == result.Length) {
            return sum == 0;
        }

        if (row < words.Length) {
            string word = words[row];

            if (col >= word.Length) {
                return Dfs(col, row + 1, sum);
            }

            char ch = word[word.Length - 1 - col];
            int idx = ch - 'A';

            if (map[idx] != -1) {
                return Dfs(col, row + 1, sum + map[idx]);
            }

            for (int digit = 0; digit <= 9; digit++) {
                if (used[digit]) continue;
                if (digit == 0 && noZero[idx]) continue;

                map[idx] = digit;
                used[digit] = true;

                if (Dfs(col, row + 1, sum + digit)) return true;

                used[digit] = false;
                map[idx] = -1;
            }

            return false;
        } else {
            char ch = result[result.Length - 1 - col];
            int idx = ch - 'A';
            int digit = sum % 10;
            int carry = sum / 10;

            if (map[idx] != -1) {
                if (map[idx] != digit) return false;
                return Dfs(col + 1, 0, carry);
            }

            if (used[digit]) return false;
            if (digit == 0 && noZero[idx]) return false;

            map[idx] = digit;
            used[digit] = true;

            if (Dfs(col + 1, 0, carry)) return true;

            used[digit] = false;
            map[idx] = -1;

            return false;
        }
    }
}
