            counts[word] = counts.ContainsKey(word) ? counts[word] + 1 : 1;
        }

        var result = new System.Collections.Generic.List<string>();

        foreach (var pair in counts) {
            if (pair.Value == 1) {
                result.Add(pair.Key);
            }
        }

        return result.ToArray();
    }
}
